#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe mqtt-keep-readings-across-restarts. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p state
printf '%s\n' 'the server'\''s data directory' > state/readme.txt
cat > wait.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh wait.sh <mqtt port> <topic> <expected reading>
port=$1
topic=$2
expected=$3
try=0
while [ "$try" -lt 20 ]; do
  # The broker sends the topic's length in two bytes, the topic, then the reading: keep what follows.
  kept=$(curl -s "mqtt://127.0.0.1:$port/$topic" | tail -c +$(( ${#topic} + 3 )))
  if [ "$kept" = "$expected" ]; then
    echo "kept: $topic is $kept"
    exit 0
  fi
  try=$(( try + 1 ))
  sleep 0.5
done
echo "not kept: $topic"
exit 1
EOF
surl --allow-anonymous --directory state --topic "sensors/#;retain" mqtt://127.0.0.1:8080/ &
sleep 1
curl -sS -d 21.5 mqtt://127.0.0.1:8080/sensors/kitchen/temp --next -sS -d 19.0 mqtt://127.0.0.1:8080/sensors/hall/temp --next -sS -d 22.0 mqtt://127.0.0.1:8080/lab/kitchen/temp --next -sS -d 21.5 mqtt://127.0.0.1:8081/sensors/kitchen/temp
sh wait.sh 8080 sensors/kitchen/temp 21.5
sh wait.sh 8080 sensors/hall/temp 19.0
sh wait.sh 8081 sensors/kitchen/temp 21.5
curl -s mqtt://127.0.0.1:8080/sensors/kitchen/temp
kill $(jobs -p)
